mapper.select:
SELECT ACCOUNT AS account, INDENTIFY_MARK AS indentifyMark, FUND_ACC AS fundAcc, FIN_ACC AS finAcc, SUM(AMOUNT_CNY) AS amountCny, IS_CONSIGN AS isConsign, BANK_MARK AS bankMark, STR_TO_DATE(DATE_STATUS,'%Y-%m-%d') AS dateStatus, GROUP_ID AS groupId FROM (SELECT ACCOUNT, INDENTIFY_MARK, FUND_ACC, FIN_ACC, (CASE WHEN BUSI_TYPE IN('01','02','05','06','11','13','14') THEN AMOUNT_CNY WHEN BUSI_TYPE IN('03','04','07','10','12','15','16') THEN 0-AMOUNT_CNY WHEN BUSI_TYPE IN('08','09') THEN 0 END) AS AMOUNT_CNY, BUSI_TYPE, (CASE WHEN IS_CONSIGN IN ('02') THEN '1018' WHEN IS_CONSIGN IN ('01') THEN SUBSTR(AGENCY_CODE,-4) END) AS IS_CONSIGN, '91110000100011743X'AS BANK_MARK, #{batchDateEnd} AS DATE_STATUS, DATA_SOURCE AS GROUP_ID FROM CHB_EQUDET WHERE STATUS IN ('E','M','A') AND EQUITY_CONF_DATE = STR_TO_DATE(#{batchDateEnd},'%Y-%m-%d')
#{prodId}
) T1 GROUP BY ACCOUNT,INDENTIFY_MARK,FUND_ACC,FIN_ACC,IS_CONSIGN,BANK_MARK,DATE_STATUS,GROUP_ID

mapper.insert:
INSERT INTO CHB_PRODUCTS_BALANCE_SUB ( REGIST_SEQNO,STATUS_BATCH,ACCOUNT, INDENTIFY_MARK,FUND_ACC,FIN_ACC, AMOUNT_CNY,IS_CONSIGN, BANK_MARK, DATE_STATUS,GROUP_ID,STATUS, CREATE_USER, ORG_CODE, CREATE_DEPT, CREATE_TIME,UPDATE_USER,UPDATE_TIME ) SELECT A.REGIST_SEQNO, A.STATUS_BATCH, A.ACCOUNT, A.INDENTIFY_MARK, A.FUND_ACC, A.FIN_ACC, A.AMOUNT_CNY, A.IS_CONSIGN, A.BANK_MARK, A.DATE_STATUS, A.GROUP_ID, A.STATUS, A.CREATE_USER, A.ORG_CODE, A.CREATE_DEPT, A.CREATE_TIME, A.UPDATE_USER, A.UPDATE_TIME FROM (
select #{item.registSeqno,jdbcType=VARCHAR} AS REGIST_SEQNO, #{item.statusBatch,jdbcType=VARCHAR} AS STATUS_BATCH,#{item.account,jdbcType=VARCHAR} AS ACCOUNT, #{item.indentifyMark,jdbcType=VARCHAR} AS INDENTIFY_MARK, #{item.fundAcc,jdbcType=VARCHAR} AS FUND_ACC, #{item.finAcc,jdbcType=VARCHAR} AS FIN_ACC, #{item.amountCny,jdbcType=DECIMAL} AS AMOUNT_CNY, #{item.isConsign,jdbcType=VARCHAR} AS IS_CONSIGN, #{item.bankMark,jdbcType=VARCHAR} AS BANK_MARK, #{item.dateStatus,jdbcType=DATE} AS DATE_STATUS, #{item.groupId,jdbcType=VARCHAR} AS GROUP_ID, #{item.status,jdbcType=VARCHAR} AS STATUS, #{item.createUser,jdbcType=VARCHAR} AS CREATE_USER, #{item.orgCode,jdbcType=VARCHAR} AS ORG_CODE, #{item.createDept,jdbcType=VARCHAR} AS CREATE_DEPT, #{item.createTime,jdbcType=TIMESTAMP} AS CREATE_TIME, #{item.updateUser,jdbcType=VARCHAR} AS UPDATE_USER, #{item.updateTime,jdbcType=TIMESTAMP} AS UPDATE_TIME from dual
) A
